137→func maskAPIKey(key string) string {
138→	if key == "" {
139→		return "(not set)"
140→	}
141→	if len(key) <= 8 {
142→		return "****"
143→	}
144→	return key[:4] + "..." + key[len(key)-4:]
145→}
