 13→
 14→// Factory provides shared dependencies for commands.
 15→type Factory struct {
 16→	Config    *config.Config
 17→	client    *api.Client
 18→	Format    string
 19→	Workspace string
 20→	Project   string
 21→	Debug     bool
 22→}
 23→
 24→// NewFactory creates a factory from config with CLI flag overrides.
 25→func NewFactory(cfg *config.Config, workspace, project, format string, debug bool) *Factory {
 26→	f := &Factory{
 27→		Config:    cfg,
 28→		Workspace: cfg.Workspace,
 29→		Project:   cfg.Project,
 30→		Format:    cfg.Format,
 31→		Debug:     debug,
 32→	}
 33→
 34→	// CLI flag overrides
 35→	if workspace != "" {
 36→		f.Workspace = workspace
 37→	}
 38→	if project != "" {
 39→		f.Project = project
 40→	}
 41→	if format != "" {
 42→		f.Format = format
 43→	}
 44→
 45→	return f
 46→}
 47→
 48→// Client returns the API client, creating it if needed.
 49→func (f *Factory) Client() (*api.Client, error) {
 50→	if f.client != nil {
 51→		return f.client, nil
 52→	}
 53→
 54→	if f.Config.BaseURL == "" {
 55→		return nil, fmt.Errorf("base URL not configured.\n  Run `plane config init` to set up your Plane instance URL")
 56→	}
 57→	if f.Config.APIKey == "" {
 58→		return nil, fmt.Errorf("API key not configured.\n  Run `plane config init` to set up your API key")
 59→	}
 60→
 61→	f.client = api.NewClient(f.Config.BaseURL, f.Config.APIKey, api.WithDebug(f.Debug))
 62→	return f.client, nil
 63→}
 64→
 65→// RequireWorkspace returns the workspace slug or an error.
 66→func (f *Factory) RequireWorkspace() (string, error) {
 67→	if f.Workspace == "" {
 68→		return "", fmt.Errorf("workspace not specified.\n  Use --workspace flag or set it with `plane config set workspace <slug>`")
 69→	}
 70→	return f.Workspace, nil
 71→}
 72→
 73→// RequireProject returns the project ID or an error.
 74→func (f *Factory) RequireProject() (string, error) {
 75→	if f.Project == "" {
 76→		return "", fmt.Errorf("project not specified.\n  Use --project flag or set it with `plane config set project <id>`")
 77→	}
 78→	return f.Project, nil
 79→}
 80→
 81→// RequireWorkspaceAndProject returns both workspace and project or errors.
 82→func (f *Factory) RequireWorkspaceAndProject() (string, string, error) {
 83→	ws, err := f.RequireWorkspace()
 84→	if err != nil {
 85→		return "", "", err
 86→	}
 87→	proj, err := f.RequireProject()
 88→	if err != nil {
 89→		return "", "", err
 90→	}
 91→	return ws, proj, nil
 92→}
