 94→// issueSeqPattern matches identifiers like "SRCH-100", "BE-42", "PROJ-1".
 95→var issueSeqPattern = regexp.MustCompile(`^[A-Za-z]+-(\d+)$`)
 96→
 97→// IsIssueIdentifier checks if the string looks like "PROJ-123" rather than a UUID.
 98→func IsIssueIdentifier(s string) bool {
 99→	return issueSeqPattern.MatchString(s)
100→}
101→
102→// ResolveIssueID resolves an issue reference to a UUID.
103→// Accepts either a UUID (returned as-is) or "PROJ-123" format (looked up via API).
104→func (f *Factory) ResolveIssueID(issueRef string) (string, error) {
105→	if !IsIssueIdentifier(issueRef) {
106→		return issueRef, nil
107→	}
108→
109→	// Parse "SRCH-100" → identifier="SRCH", seqNum=100
110→	parts := strings.SplitN(issueRef, "-", 2)
111→	if len(parts) != 2 {
112→		return "", fmt.Errorf("invalid issue identifier: %s (expected format: PROJ-123)", issueRef)
113→	}
114→	identifier := strings.ToUpper(parts[0])
115→	seqNum, err := strconv.Atoi(parts[1])
116→	if err != nil {
117→		return "", fmt.Errorf("invalid sequence number in %s: %w", issueRef, err)
118→	}
119→
120→	client, err := f.Client()
121→	if err != nil {
122→		return "", err
123→	}
124→	ws, err := f.RequireWorkspace()
125→	if err != nil {
126→		return "", err
127→	}
128→
129→	// First, find the project by identifier
130→	projectID, err := f.resolveProjectByIdentifier(client, ws, identifier)
131→	if err != nil {
132→		return "", fmt.Errorf("resolving project for %s: %w", issueRef, err)
133→	}
134→
135→	// Look up the issue by scanning pages for matching sequence_id.
136→	// Plane API does not support filtering by sequence_id as a query parameter.
137→	cursor := ""
138→	for {
139→		p := api.NewPath("workspaces/{workspace_slug}/projects/{project_id}/work-items/").
140→			Workspace(ws).Project(projectID).
141→			QueryInt("per_page", 100)
142→		if cursor != "" {
143→			p.Query("cursor", cursor)
144→		}
145→
146→		path, err := p.Build()
147→		if err != nil {
148→			return "", err
149→		}
150→
151→		resp, err := client.Get(path)
152→		if err != nil {
153→			return "", fmt.Errorf("looking up %s: %w", issueRef, err)
154→		}
155→
156→		var paginated struct {
157→			Results []struct {
158→				ID         string `json:"id"`
159→				SequenceID int    `json:"sequence_id"`
160→			} `json:"results"`
161→			NextPage   bool   `json:"next_page_results"`
162→			NextCursor string `json:"next_cursor"`
163→		}
164→		if err := json.Unmarshal(resp, &paginated); err == nil {
165→			for _, item := range paginated.Results {
166→				if item.SequenceID == seqNum {
167→					return item.ID, nil
168→				}
169→			}
170→			if !paginated.NextPage || paginated.NextCursor == "" {
171→				break
172→			}
173→			cursor = paginated.NextCursor
174→			continue
175→		}
176→
177→		// Fallback: try direct array
178→		var issues []struct {
179→			ID         string `json:"id"`
180→			SequenceID int    `json:"sequence_id"`
181→		}
182→		if err := json.Unmarshal(resp, &issues); err == nil {
183→			for _, item := range issues {
184→				if item.SequenceID == seqNum {
185→					return item.ID, nil
186→				}
187→			}
188→		}
189→		break
190→	}
191→
192→	return "", fmt.Errorf("issue %s not found", issueRef)
193→}
194→
195→// resolveProjectByIdentifier finds a project UUID by its identifier (e.g., "SRCH").
196→func (f *Factory) resolveProjectByIdentifier(client *api.Client, ws, identifier string) (string, error) {
197→	// If we already have a project set and it matches, use it
198→	if f.Project != "" {
199→		return f.Project, nil
200→	}
201→
202→	path, err := api.NewPath("workspaces/{workspace_slug}/projects/").
203→		Workspace(ws).Build()
204→	if err != nil {
205→		return "", err
206→	}
207→
208→	resp, err := client.Get(path)
209→	if err != nil {
210→		return "", err
211→	}
212→
213→	// Try paginated response
214→	var paginated struct {
215→		Results []struct {
216→			ID         string `json:"id"`
217→			Identifier string `json:"identifier"`
218→		} `json:"results"`
219→	}
220→	if err := json.Unmarshal(resp, &paginated); err == nil && len(paginated.Results) > 0 {
221→		for _, p := range paginated.Results {
222→			if strings.EqualFold(p.Identifier, identifier) {
223→				return p.ID, nil
224→			}
225→		}
226→	}
227→
228→	// Try direct array
229→	var projects []struct {
230→		ID         string `json:"id"`
231→		Identifier string `json:"identifier"`
232→	}
233→	if err := json.Unmarshal(resp, &projects); err == nil {
234→		for _, p := range projects {
235→			if strings.EqualFold(p.Identifier, identifier) {
236→				return p.ID, nil
237→			}
238→		}
239→	}
240→
241→	return "", fmt.Errorf("project with identifier %q not found in workspace %q", identifier, ws)
242→}
