 7→// Formatter defines the interface for output formatting.
 8→type Formatter interface {
 9→	Format(data interface{}) error
10→}
11→
12→// Format outputs data using the specified format.
13→func Format(format string, data interface{}, columns []Column) error {
14→	switch format {
15→	case "table":
16→		return NewTableFormatter(columns).Format(data)
17→	default:
18→		return NewJSONFormatter().Format(data)
19→	}
20→}
21→
22→// FormatRaw outputs raw JSON data.
23→func FormatRaw(format string, data json.RawMessage, columns []Column) error {
24→	switch format {
25→	case "table":
26→		return NewTableFormatter(columns).Format(data)
27→	default:
28→		return NewJSONRawFormatter().Format(data)
29→	}
30→}
31→
32→// Column defines a table column.
33→type Column struct {
34→	Header string
35→	Field  string
36→	Width  int
37→}
38→
39→// InjectField adds a field to a JSON response (object or array of objects).
40→func InjectField(data json.RawMessage, key string, value interface{}) json.RawMessage {
41→	// Try single object
42→	var obj map[string]interface{}
43→	if err := json.Unmarshal(data, &obj); err == nil {
44→		obj[key] = value
45→		out, _ := json.Marshal(obj)
46→		return out
47→	}
48→
49→	// Try array
50→	var arr []map[string]interface{}
51→	if err := json.Unmarshal(data, &arr); err == nil {
52→		for i := range arr {
53→			arr[i][key] = value
54→		}
55→		out, _ := json.Marshal(arr)
56→		return out
57→	}
58→
59→	return data
60→}
