 8→
 9→// APIError represents an error returned by the Plane API.
10→type APIError struct {
11→	StatusCode int
12→	Status     string
13→	Message    string
14→	Detail     string
15→	Raw        string
16→}
17→
18→func (e *APIError) Error() string {
19→	if e.Detail != "" {
20→		return fmt.Sprintf("%s: %s", e.Status, e.Detail)
21→	}
22→	if e.Message != "" {
23→		return fmt.Sprintf("%s: %s", e.Status, e.Message)
24→	}
25→	return e.Status
26→}
27→
28→// HelpText returns actionable suggestions for common errors.
29→func (e *APIError) HelpText() string {
30→	switch e.StatusCode {
31→	case http.StatusUnauthorized:
32→		return "Your API key may be invalid or expired.\n" +
33→			"  Run `plane config init` to set up a new API key.\n" +
34→			"  Generate keys at your Plane instance settings."
35→	case http.StatusForbidden:
36→		return "You don't have permission for this action.\n" +
37→			"  Check your role in the workspace/project."
38→	case http.StatusNotFound:
39→		return "The requested resource was not found.\n" +
40→			"  Verify the workspace slug, project ID, and resource ID."
41→	case http.StatusTooManyRequests:
42→		return "Rate limit exceeded (60 req/min).\n" +
43→			"  Wait a moment and try again."
44→	case http.StatusUnprocessableEntity:
45→		return "The request data is invalid.\n" +
46→			"  Check the required fields and their formats."
47→	default:
48→		return ""
49→	}
50→}
51→
52→// parseAPIError parses an API error from an HTTP response.
53→func parseAPIError(resp *http.Response, body []byte) *APIError {
54→	apiErr := &APIError{
55→		StatusCode: resp.StatusCode,
56→		Status:     resp.Status,
57→		Raw:        string(body),
58→	}
59→
60→	// Try to parse JSON error response
61→	var errResp map[string]interface{}
62→	if err := json.Unmarshal(body, &errResp); err == nil {
63→		if msg, ok := errResp["error"].(string); ok {
64→			apiErr.Message = msg
65→		}
66→		if detail, ok := errResp["detail"].(string); ok {
67→			apiErr.Detail = detail
68→		}
69→		if msg, ok := errResp["message"].(string); ok {
70→			apiErr.Message = msg
71→		}
72→	}
73→
74→	return apiErr
75→}
